-- Create "sessions" table
CREATE TABLE "public"."sessions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "token" character varying NOT NULL,
  "data" bytea NOT NULL,
  "expiry" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "session_expiry" to table: "sessions"
CREATE INDEX "session_expiry" ON "public"."sessions" ("expiry");
-- Create index "sessions_token_key" to table: "sessions"
CREATE UNIQUE INDEX "sessions_token_key" ON "public"."sessions" ("token");
-- Create "users" table
CREATE TABLE "public"."users" (
  "id" uuid NOT NULL,
  "email" character varying NOT NULL,
  "nickname" character varying NOT NULL,
  "password_hash" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "user_created_at" to table: "users"
CREATE INDEX "user_created_at" ON "public"."users" ("created_at");
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "public"."users" ("email");
-- Create index "users_nickname_key" to table: "users"
CREATE UNIQUE INDEX "users_nickname_key" ON "public"."users" ("nickname");
